+
+// ---------- 4. Self-serve cancel / terminate (+ prorated refund) ----------
+
+/**
+ * Customer-initiated cancellation of a VPS / game server. Two modes:
+ *
+ *   • "period_end"  — stop auto-renew and keep the server running until `expiresAt`.
+ *                     No money moves; the paid term is honoured to its end. Default
+ *                     and always-safe choice.
+ *   • "immediate"   — terminate NOW: enqueue the SAME audited DELETE job the manual
+ *                     delete uses (worker destroys the VM), and — for a standard VPS
+ *                     with unused paid time — credit the prorated refund to the WALLET
+ *                     (never a Stripe refund; safer and reversible) in the same
+ *                     transaction, with a ledger line and a credit-note invoice.
+ *
+ * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
+ * can move money — an admin must not do either on a customer's behalf). Respects the
+ * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
+ * warning and the refund figure.
+ */
+export async function cancelService(
+  serverId: string,
+  mode: "immediate" | "period_end",
+): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
+  // Moves money and destroys a resource — never while impersonating.
+  await assertNotImpersonating();
+  const { user, server } = await ownedServer(serverId);
+
+  if (server.status === "DELETING") return { error: "This server is already being cancelled." };
+
+  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
+  if (mode === "period_end") {
+    if (server.isFree || !server.expiresAt) {
+      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
+    }
+    if (!server.autoRenew) {
+      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
+    }
+    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
+    await db.auditLog.create({
+      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
+    });
+    revalidatePath(`/dashboard/servers/${serverId}`);
+    return {
+      ok: true,
+      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
+    };
+  }
+
+  // ---- Immediate termination (+ prorated wallet refund). ----
+  if (await hasInflightJob(serverId)) {
+    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
+  }
+
+  const refundCents = terminationRefundCents({
+    isFree: server.isFree,
+    expiresAt: server.expiresAt,
+    isGame: !!server.gamePlanId,
+    planMonthlyCents: server.plan.priceCents,
+    termMonths: server.termMonths,
+    termPromoPercent: server.termPromoPercent,
+    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
+  });
+
+  // One transaction: the refund credit (if any), the DELETE job and the status flip
+  // either all commit or none do — a terminated server can never be left un-refunded,
+  // and a refund can never be issued without the termination that earns it.
+  await db.$transaction([
+    ...(refundCents > 0
+      ? [
+          db.user.update({
+            where: { id: server.userId },
+            data: { balanceCents: { increment: refundCents } },
+          }),
+          db.walletTransaction.create({
+            data: {
+              userId: server.userId,
+              amountCents: refundCents,
+              description: `Cancellation refund (unused term) — ${server.hostname}`,
+            },
+          }),
+          // A credit-note invoice for the refund, so the ledger line has a matching
+          // billing document the customer can download. Marked REFUNDED.
+          db.invoice.create({
+            data: invoiceCreateData({
+              userId: server.userId,
+              description: `Cancellation refund — ${server.hostname}`,
+              status: "REFUNDED",
+              lineItems: [
+                {
+                  description: `Prorated refund for unused term — ${server.hostname}`,
+                  qty: 1,
+                  unitCents: refundCents,
+                  amountCents: refundCents,
+                },
+              ],
+            }),
+          }),
+        ]
+      : []),
+    db.server.update({ where: { id: server.id }, data: { status: "DELETING", autoRenew: false } }),
+    db.job.create({ data: { type: "DELETE", serverId } }),
+    db.auditLog.create({
+      data: {
+        userId: user.id,
+        action: "server.cancel_immediate",
+        detail: `${serverId} refund=${refundCents}`,
+      },
+    }),
+  ]);
+
+  if (refundCents > 0) {
+    await db.notification
+      .create({
+        data: {
+          userId: server.userId,
+          title: `Refund of $${(refundCents / 100).toFixed(2)} credited to your wallet`,
+          body: `We refunded the unused portion of ${server.hostname}'s term as wallet credit. Your data on this server is being erased and cannot be recovered.`,
+          href: "/dashboard/billing",
+        },
+      })
+      .catch(() => {});
+  }
+
+  revalidatePath(`/dashboard/servers/${serverId}`);
+  return {
+    ok: true,
+    refundCents,
