// Spend caps + monthly-budget alerts (Finding 3). Plain server module.
//
// "Spend" here means MONEY ACTUALLY CHARGED FOR SERVICES this calendar month: the
// sum of the negative `WalletTransaction` amounts (orders, renewals, resizes). Wallet
// TOP-UPS are positive credits and are never counted — adding money to the wallet is
// not spending it, and a hard cap must never block a customer topping up to pay a
// bill. Refund credits are likewise positive and excluded.
//
// Two features, both opt-in and both defaulting OFF so an account that has not
// configured them behaves exactly as before:
//   • a SOFT monthly budget that emails once when spend first crosses it, and
//   • a HARD monthly cap that REFUSES a new paid order / manual wallet renewal that
//     would push spend past it.
//
// The hard cap is enforced at the discretionary spend paths (placeOrder, renewNow),
// NOT in the automatic auto-renew sweep: a standing auto-renew instruction must not
// silently lapse and destroy an existing server because of a budget number.

import { db } from "./db";
import type { Prisma } from "@prisma/client";

export class SpendCapError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SpendCapError";
  }
}

/** "YYYY-MM" for a date in UTC — the bucket both spend-to-date and the alert use. */
export function monthKey(d: Date = new Date()): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

/** First instant of the current UTC calendar month. */
export function startOfMonth(d: Date = new Date()): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1));
}

/**
 * Service spend (in cents, positive) for this account so far this calendar month:
 * the magnitude of every negative wallet transaction since the month began. Runs on
 * the passed transaction client when given one so a caller can read it inside the
 * same tx that is about to debit.
 */
export async function monthSpendCents(
  userId: string,
  client: Prisma.TransactionClient | typeof db = db,
  now: Date = new Date(),
): Promise<number> {
  const agg = await client.walletTransaction.aggregate({
    where: { userId, amountCents: { lt: 0 }, createdAt: { gte: startOfMonth(now) } },
    _sum: { amountCents: true },
  });
  return Math.abs(agg._sum.amountCents ?? 0);
}

/**
 * Refuse a new discretionary charge of `addCents` when the account has a hard cap
 * enabled and this charge would push month-to-date spend past it. No-op when the cap
 * is disabled or unset. Throws SpendCapError (a clear, customer-facing message) so
 * the order/renew action can surface it verbatim.
 *
 * Advisory-but-safe: the cap is the customer's OWN limit, not a security boundary, so
 * a read-then-charge check is acceptable; it is called immediately before the debit.
 */
export async function assertSpendCap(
  user: { id: string; spendCapEnabled?: boolean; hardCapCents?: number | null },
  addCents: number,
  client: Prisma.TransactionClient | typeof db = db,
): Promise<void> {
  if (!user.spendCapEnabled || user.hardCapCents == null || addCents <= 0) return;
  const cap = user.hardCapCents;
  const spent = await monthSpendCents(user.id, client);
  if (spent + addCents > cap) {
    const remain = Math.max(0, cap - spent);
    throw new SpendCapError(
      `This purchase ($${(addCents / 100).toFixed(2)}) would exceed your monthly spend cap of ` +
        `$${(cap / 100).toFixed(2)} — you have $${(remain / 100).toFixed(2)} left this month. ` +
        `Raise or turn off the cap in Billing to continue.`,
    );
  }
}

/**
 * After a charge lands, email the customer at most ONCE per calendar month the first
 * time their month-to-date spend crosses their soft budget. Best-effort and
 * idempotent via `budgetAlertedPeriod`; never throws into the charge path.
 */
export async function maybeAlertBudget(userId: string): Promise<void> {
  try {
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user || !user.budgetAlertEnabled || user.monthlyBudgetCents == null) return;
    const period = monthKey();
    if (user.budgetAlertedPeriod === period) return; // already told them this month
    const spent = await monthSpendCents(userId);
    if (spent < user.monthlyBudgetCents) return;
    // Stamp FIRST (idempotency): only the writer that flips the period from "not this
    // month" sends, so two concurrent charges can't both email.
    const stamped = await db.user.updateMany({
      where: { id: userId, budgetAlertedPeriod: user.budgetAlertedPeriod ?? null },
      data: { budgetAlertedPeriod: period },
    });
    if (stamped.count !== 1) return;
    await db.notification.create({
      data: {
        userId,
        title: `You've reached your monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)}`,
        body: `Your Nxeon service spend this month is $${(spent / 100).toFixed(2)}. This is a heads-up only — nothing is blocked. Set a hard spend cap in Billing if you want new purchases stopped automatically.`,
        href: "/dashboard/billing",
      },
    });
    try {
      const { sendMail, emails } = await import("./mailer");
      const tpl = (emails as any).budgetAlert
        ? (emails as any).budgetAlert(user.monthlyBudgetCents, spent)
        : {
            subject: `Nxeon: monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)} reached`,
            html: `<p>Your Nxeon service spend this month is <b>$${(spent / 100).toFixed(2)}</b>, which has reached the monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)} you set.</p><p>This is a notification only — nothing has been blocked. You can review spend and set a hard cap in your <a href="/dashboard/billing">billing settings</a>.</p>`,
          };
      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId, kind: "invoice" });
    } catch {
      /* best-effort mail */
    }
  } catch {
    /* never break a charge because an alert failed */
  }
}

// Pure, dependency-free proration maths shared by the server actions (resize,
// disk expansion, downgrade) and the client pickers that DISPLAY the number.
// No server-only imports, exactly like lib/wallet-split.ts — so the figure the
// customer sees is byte-for-byte the figure that gets charged or credited.
//
// NOTHING IN HERE READS THE CLOCK FOR A PRICE. Every input is passed in. Until
// 2026-07-26 the rate basis defaulted to `currentPromo(new Date())`, which meant
// the customer set the price of a resize by choosing the day they clicked — see
// `resolveTermPromoPercent`. This module must never import `currentPromo` again.

import { vpsEffectiveMonthly } from "./billing-terms";
import { deepestPromoPercent, discountedCents } from "./promotions";

/** Average calendar month in ms (365.25/12 ≈ 30.44d). */
export const MS_PER_AVG_MONTH = 30.44 * 86400_000;

/**
 * Months of paid term left at `now` — 0 when there is no expiry (free/admin
 * servers) and clamped at zero so an already-expired term never prorates
 * negatively.
 *
 * There is deliberately NO cap parameter, and re-adding one would reopen a money
 * bug. `expiresAt` only ever moves forward in exchange for payment: the initial
 * order term (lib/order.ts, lib/actions.ts placeOrder), `renewNow`
 * (lib/actions.ts) and the auto-renew sweep (worker/billing.ts) each advance it by
 * exactly `termMonths` and charge `vpsTermPriceCents` for those months. So every
 * month between `now` and `expiresAt` is a month the customer has actually bought,
 * however many terms of "Renew now" are stacked up in there, and the honest
 * prorated figure covers all of them.
 *
 * This used to take `capMonths`, and that optional knob is precisely how the two
 * directions drifted apart: the upgrade path (lib/resize.ts) passed no cap while
 * the downgrade path (lib/actions-server-lifecycle.ts) passed `server.termMonths`.
 * A customer who had stacked "Renew now" out to 36 months on a 12-month term was
 * charged $544.32 to move Starter -> Max and credited only $181.44 to move
 * straight back — the platform kept $362.88 it never earned. Four call sites
 * (two servers, two pickers) had to agree on that argument by convention, and they
 * did not. With the knob gone every caller gets the same number from the same
 * one-argument call, so the round-trip invariant is structural instead of a
 * comment someone has to honour.
 *
 * A cap was never what protected the credit side either. The credit is
 * `(effective(from) - effective(to)) x months` priced through `prorateDeltaCents`
 * at the term-discounted AND promo-reduced rate, while the renewal paths charge
 * the term price with no promo applied — so the credit for a given month is
 * strictly less than what that month cost. What made the old credit a money
 * printer was the RAW LIST-price delta it used before 2026-07-25, not the number
 * of months it spanned.
 */
export function remainingMonths(expiresAt: Date | null, now: number): number {
  if (!expiresAt) return 0;
  return Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
}

/**
 * The rate basis for a proration, resolved from what the server row records.
 *
 * `Server.termPromoPercent` is the percent off the term-discounted monthly rate
 * that the months currently left on `expiresAt` were ACTUALLY sold at. NULL means
 * the row predates that column and the rate is unknown.
 *
 * ─── WHY NULL MUST NOT FALL THROUGH TO `currentPromo(now)` ──────────────────
 * That was the bug, fixed 2026-07-26. `prorateDeltaCents` used to default its rate
 * basis to the seasonal promo running at the instant of the call. Promos rotate by
 * calendar date from a 15% Launch Sale up to 45% for Cyber Monday (lib/promotions.ts),
 * so both halves of a round trip were priced off a number the CUSTOMER got to choose
 * by picking the date. Upgrade on Cyber Monday: the delta is charged at 55% of the
 * honest rate. Downgrade back in mid-January: the same delta is credited at 85%.
 * The 30-point spread x plan delta x every remaining month falls straight into the
 * wallet, repeatable every promo cycle, with the platform's own marketing calendar
 * published as the timetable. On the pinned catalogue (Starter 899 -> Max 3299, a
 * 36-month term) that is $207.36 of minted cash per cycle for zero net change.
 *
 * It was also simply the wrong rate. lib/promotions.ts states in its opening line
 * that a promo discounts a customer's FIRST TERM only and that renewals never get
 * it — yet this priced a mid-term plan change, on months that may well have been
 * bought at a renewal's full price, off a promo the customer was never sold.
 *
 * ─── THE FALLBACK, AND WHY IT IS THE DEEPEST DISCOUNT AND NOT FULL PRICE ────
 * The obvious conservative guess is "assume they paid full list" (percent 0). It is
 * the wrong direction and it MINTS MONEY. A credit is monotonically INCREASING in
 * the rate basis, so percent 0 produces the LARGEST credit this function can emit.
 * A customer who really bought Max on a 36-month term during Cyber Monday paid
 * 0.55 x 2639 = 1451c per month-equivalent; a downgrade to Starter priced at
 * percent 0 credits (2639 - 719) = 1920c per month — 469c/month MORE than they ever
 * paid, so 36 months hands back $168.84 of cash they never spent AND leaves them a
 * running Starter VPS for three years.
 *
 * So the fallback goes the other way: assume the LEAST the platform has ever
 * charged (`deepestPromoPercent()`, currently the 45% Cyber Monday). Under that
 * basis the credit is bounded below the real cash for every rate the customer could
 * actually have been sold. The price of being wrong in this direction is a cheaper
 * upgrade for an unknown-rate server — a pricing concession, not a printer: it can
 * only ever reduce revenue collected, never push cash OUT, and because BOTH
 * directions read this same resolved number a round trip still nets to exactly
 * zero. Given the choice between under-charging and over-refunding, this file's
 * entire incident history says take the under-charge.
 *
 * (After scripts/backfill-term-promo-percent.ts this branch is unreachable on live
 * data — every row carries a rate derived from what it was actually invoiced.)
 */
export function resolveTermPromoPercent(termPromoPercent: number | null | undefined): number {
  if (termPromoPercent === null || termPromoPercent === undefined) return deepestPromoPercent();
  // A stored value outside 0-100 would invert or amplify the delta; clamp rather
  // than trust, since this number is a direct multiplier on money.
  return Math.min(100, Math.max(0, termPromoPercent));
}

/**
 * The value-weighted blend of the rate the remaining months are already on and the
 * rate a freshly-added block of months is being sold at.
 *
 * `termPromoPercent` is ONE scalar covering every month left on `expiresAt`, but
 * months get added to that window at different rates: an intro-discounted first
 * term, then renewals at full price, and occasionally an admin gift at no price at
 * all. Overwriting the scalar on each addition would silently reprice the months
 * already in there — and in the profitable direction. Concretely: buy a 36-month
 * term at 45% off, click "Renew now" once (which honestly charges full price for 36
 * more months), and a plain overwrite would re-rate the original 36 discounted
 * months to full price too, restoring the exact same spread this field exists to
 * kill. Blending keeps the total cash value of the remaining window invariant:
 * added months contribute their own rate and nothing reprices what came before.
 *
 * The result is deliberately NOT rounded to a whole percent, which is why the
 * column is a Float: 36 months at 45% off plus 36 renewed months at full price is
 * exactly 22.5% off, and rounding that to 23 shaves $7.20 off the $1,071.36 credit
 * those 72 months are worth. Rounding here would also compound over a server's
 * lifetime, once per renewal. (It could never break the round-trip invariant —
 * both directions read the same stored scalar whatever it holds — but "symmetric"
 * and "correct" are different properties and this file owes the customer both.)
 */
export function prorateBlendPercent(opts: {
  /** Rate the months already on the clock were sold at (already resolved). */
  currentPercent: number;
  /** How many months are already on the clock. */
  currentMonths: number;
  /** Rate the newly-added months are being sold at. 0 = full price, 100 = gifted. */
  addedPercent: number;
  /** How many months are being added. Non-positive => nothing to blend. */
  addedMonths: number;
}): number {
  const cur = Math.min(100, Math.max(0, opts.currentPercent));
  const add = Math.min(100, Math.max(0, opts.addedPercent));
  const curMonths = Math.max(0, opts.currentMonths);
  const addMonths = Math.max(0, opts.addedMonths);
  const total = curMonths + addMonths;
  // Nothing on the clock and nothing added: keep the incoming rate rather than
  // divide by zero. (Also the honest answer for "term shortened, none added" —
  // fewer months at the same rate, which is exactly what the caller wants.)
  if (total <= 0) return cur;
  const value = curMonths * (1 - cur / 100) + addMonths * (1 - add / 100);
  const pct = 100 * (1 - value / total);
  // Snap off binary-float noise only: 36mo at 45% blended with 36mo at 0% is
  // exactly 22.5 but computes as 22.500000000000007, and blending a rate with
  // itself must be an exact no-op rather than drifting a hair on every renewal.
  // Six decimal places is a millionth of a percentage point — far below a cent on
  // any conceivable term — while leaving every genuine fraction intact.
  return Math.min(100, Math.max(0, Math.round(pct * 1e6) / 1e6));
}

/**
 * The prorated difference between two monthly plan prices over the remaining
 * term, priced against THE RATE THIS SERVER'S TERM WAS ACTUALLY SOLD AT.
 *
 * Why the rate is a required argument (2026-07-26): it used to default to
 * `currentPromo(now)`, which handed the customer the pricing basis for both halves
 * of a round trip — see `resolveTermPromoPercent` for the full arbitrage. Making it
 * required means a call site cannot forget it; there is no basis to fall back TO.
 *
 * Why this exists at all (2026-07-25): proration used the raw list monthly delta
 * while the original purchase applied BOTH the term discount (lib/order.ts) and the
 * seasonal promo. Upgrading therefore cost far more than buying the target plan
 * outright for the same end date — on a 36-month term with a 30% promo running,
 * $1,044.45 to upgrade versus $665.08 fresh: the customer overpaid $379.37. The
 * mirror image was worse in kind: the downgrade CREDIT used the same undiscounted
 * delta, so it refunded more than was ever paid.
 *
 * Both directions price off the SAME function and the SAME persisted scalar, so
 * they cannot drift apart:
 *   effective monthly (term discount) → term's sold rate → × months left.
 */
export function prorateDeltaCents(opts: {
  fromMonthlyCents: number;
  toMonthlyCents: number;
  termMonths: number;
  monthsRemaining: number;
  /**
   * `Server.termPromoPercent` — percent off that THIS server's remaining months
   * were sold at. Pass the row value straight through, null and all; it is
   * resolved here so every call site resolves it identically.
   */
  termPromoPercent: number | null;
  /**
   * The admin-configured ANNUAL discount (percent) from `annualDiscountPct()`.
   *
   * OPTIONAL — unlike the renewal-pricing field in lib/renewal-charge.ts, which is
   * required. Two reasons it is safe optional here: it only bites a 12-month server
   * (every other `termMonths` ignores it via `termDiscountPct`), and when omitted it
   * falls back to the shipped default — the same number the annual term shipped at.
   * Server-side resize paths (lib/resize.ts, lib/actions-server-lifecycle.ts) and
   * the resize UIs DO pass the live value, so an annual server's mid-term upgrade
   * and downgrade credit price against the SAME rate its order and renewals use;
   * left off, the maths is unchanged for every non-annual term and matches the
   * default for annual.
   */
  annualDiscountPct?: number;
}): number {
  const pct = resolveTermPromoPercent(opts.termPromoPercent);
  const eff = (monthly: number) =>
    discountedCents(vpsEffectiveMonthly(monthly, opts.termMonths, opts.annualDiscountPct), pct);
  const delta = eff(opts.toMonthlyCents) - eff(opts.fromMonthlyCents);
  return Math.round(delta * Math.max(0, opts.monthsRemaining));
}

/** Upgrade charge — never negative. */
export function prorateUpgradeCents(opts: Parameters<typeof prorateDeltaCents>[0]): number {
  return Math.max(0, prorateDeltaCents(opts));
}

/** Downgrade credit — never negative; caller passes from=old, to=new. */
export function prorateDowngradeCreditCents(
  opts: Parameters<typeof prorateDeltaCents>[0]
): number {
  return Math.max(0, -prorateDeltaCents(opts));
}

