 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
 * quote, which it computed moments ago in the same request. See OrderPrice.
 */
/**
 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
 * any failure so nothing partial survives. Kept separate from the order tx so a
 * wallet order can surface the failure before any money moves, and a card order
 * (already paid) can swallow it without stranding the paid provision.
 *
 * Guards, all enforced here: first-time-only (no prior paid server), the
 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
 * (the two @@unique constraints on CouponRedemption).
 */
async function claimOrderCoupon(opts: {
  couponId: string;
  maxRedemptions: number | null;
  firstTimeOnly: boolean;
  userId: string;
  ipHash: string | null;
  amountCents: number;
}): Promise<void> {
  await db.$transaction(async (tx) => {
    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
    // not stand between them and this coupon on a fresh (wallet) order — and its global
    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
    if (opts.firstTimeOnly) {
      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
    }
    // Atomic conditional increment — the only thing between the last free slot and
    // an over-redemption when two orders race for it.
    const claim = await tx.coupon.updateMany({
      where:
        opts.maxRedemptions === null
          ? { id: opts.couponId, active: true }
          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
      data: { timesRedeemed: { increment: 1 } },
    });
    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
    try {
      await tx.couponRedemption.create({
        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
      });
    } catch {
      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
      // this person. Throwing rolls back the increment above with it.
      throw new OrderError("You’ve already used this code.");
    }
  });
}

/**
 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
 *
 * The card leg discounts `cardCents` up front and only settles the redemption
 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
 * paid provision is never stranded. Without this pre-check, a customer who has
 * already used a one-per-person code (or isn't first-time) still gets the
 * discounted card charge and the swallow hides it. So before we send them to
 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
 * plain reads; if any fails the caller re-quotes at full price. This is advisory
 * (a race could still lose the atomic claim at settle time — that path stays
 * swallowed by design), but it closes the everyday bypass.
 */
export async function orderCouponClaimable(opts: {
  couponId: string;
  firstTimeOnly: boolean;
  maxRedemptions: number | null;
  userId: string;
  ipHash: string | null;
}): Promise<{ ok: true } | { ok: false; error: string }> {
  if (opts.firstTimeOnly) {
    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
  }
  const byUser = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
  });
  if (byUser) return { ok: false, error: "You’ve already used this code." };
  if (opts.ipHash) {
    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
  }
  if (opts.maxRedemptions !== null) {
    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
  }
  return { ok: true };
}

