export function couponOrderDiscountCents(coupon: OrderCoupon, ctx: OrderContext, now: Date): CouponOrderVerdict {
  if (!coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.kind === "CREDIT_CENTS") return { ok: false, error: "That code is for wallet credit, not checkout." };
  if (coupon.expiresAt && coupon.expiresAt.getTime() < now.getTime()) return { ok: false, error: "That code has expired." };
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "That code has been fully claimed." };
  }
  if (!couponMatchesService(coupon, ctx)) {
    return { ok: false, error: "That code doesn’t apply to this plan." };
  }
  if (coupon.minAmountCents !== null && ctx.planChargeCents < coupon.minAmountCents) {
    return { ok: false, error: `This code needs an order of at least $${(coupon.minAmountCents / 100).toFixed(2)}.` };
  }

  const term = Math.max(1, Math.floor(ctx.termMonths || 1));
  // How many months the discount may touch — the "no year free" cap.
  let cappedMonths = coupon.maxTermMonths && coupon.maxTermMonths > 0 ? Math.min(coupon.maxTermMonths, term) : term;
  // Defence in depth for a 100%-off PERCENT code with NO month cap: without this it would
  // zero the ENTIRE term, gifting a whole 12/24/36-month VPS for free. Coupon creation now
  // refuses such a code (lib/actions-growth.ts adminCreateCoupon), but any row that predates
  // that guard is clamped HERE to a single month — the safe floor a "100% off" should mean.
  if (coupon.kind === "PERCENT" && coupon.value >= 100 && !(coupon.maxTermMonths && coupon.maxTermMonths > 0)) {
    cappedMonths = 1;
  }

  let discount: number;
  if (coupon.kind === "PERCENT") {
    const pct = Math.min(100, Math.max(0, coupon.value));
    // The discountable base is the capped months at the REGULAR monthly price —
    // not the whole (possibly term-discounted) charge — so "1 month free" is one
    // month of the plan regardless of a 12-month term's own discount.
    const base = Math.min(ctx.planMonthlyCents * cappedMonths, ctx.planChargeCents);
    discount = Math.round((base * pct) / 100);
  } else {
    discount = coupon.value;
  }

  discount = Math.max(0, Math.min(discount, ctx.planChargeCents));
  if (discount <= 0) return { ok: false, error: "That code has no effect on this order." };
  return { ok: true, discountCents: discount, label: describe(coupon, cappedMonths, term) };
}

